def search(nums, target, lo, hi):
    if lo > hi:
        return False
    mid = (lo + hi) // 2
    if nums[mid] == target:
        return True
    if nums[mid] < target:
        return search(nums, target, mid + 1, hi)
    return search(nums, target, lo, mid - 1)

def find(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid
        else:
            hi = mid - 1
    return -1

def merge(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    return result

def merge_sort(nums):
    if len(nums) <= 1:
        return nums
    mid = len(nums) // 2
    left = merge_sort(nums[:mid])
    right = merge_sort(nums[mid:])
    out = []
    while left and right:
        if left[0] <= right[0]:
            out.append(left.pop(0))
        else:
            out.append(right.pop(0))
    return out + left + right

def escape(maze, r, c):
    if r < 0 or r >= len(maze):
        return False
    if c < 0 or c >= len(maze[0]):
        return False
    if maze[r][c] == "#":
        return False
    if maze[r][c] == "E":
        return True
    return (escape(maze, r + 1, c)
            or escape(maze, r - 1, c)
            or escape(maze, r, c + 1)
            or escape(maze, r, c - 1))

MOVES = [(1, 0), (-1, 0), (0, 1), (0, -1)]

def escape(maze, r, c, seen):
    if not 0 <= r < len(maze):
        return False
    if not 0 <= c < len(maze[r]):
        return False
    if maze[r][c] == "#" or (r, c) in seen:
        return False
    if maze[r][c] == "E":
        return True
    seen.add((r, c))
    for dr, dc in MOVES:
        if escape(maze, r + dr, c + dc, seen):
            return True
    return False

