def escape(maze, r, c):
    if not (0 <= r < len(maze)
            and 0 <= c < len(maze[0])):
        return False
    if maze[r][c] == "E":
        return True
    if maze[r][c] != ".":
        return False
    maze[r][c] = "v"
    return (escape(maze, r + 1, c)
            or escape(maze, r - 1, c)
            or escape(maze, r, c + 1)
            or escape(maze, r, c - 1))

def paths(rows, cols):
    if rows == 1 or cols == 1:
        return 1
    down = paths(rows - 1, cols)
    right = paths(rows, cols - 1)
    return down + right

def choose(n, k):
    if k == 0 or k == n:
        return 1
    return choose(n - 1, k - 1) + choose(n - 1, k)

def binary(n, path):
    if len(path) == n:
        print("".join(path))
        return
    for bit in "01":
        path.append(bit)
        binary(n, path)

def perms(items, path, result):
    if len(path) == len(items):
        result.append(path[:])
        return
    for x in items:
        if x not in path:
            path.append(x)
            perms(items, path, result)
            path.pop()

def can_make(nums, i, target):
    if target == 0:
        return True
    if i == len(nums):
        return False
    if nums[i] > target:
        return False
    rest = target - nums[i]
    return (can_make(nums, i + 1, rest)
            or can_make(nums, i + 1, target))

def can_make(nums, i, target):
    if target == 0:
        return True
    if i == len(nums):
        return False
    if nums[i] <= target:
        rest = target - nums[i]
        if can_make(nums, i + 1, rest):
            return True
    return can_make(nums, i + 1, target)

def ways(amount, coins):
    if amount == 0:
        return 1
    if amount < 0:
        return 0
    total = 0
    for c in coins:
        total += ways(amount - c, coins)
    return total

def spell(grid, word, r, c):
    if word == "":
        return True
    if r < 0 or r >= len(grid):
        return False
    if c < 0 or c >= len(grid[0]):
        return False
    if grid[r][c] != word[0]:
        return False
    grid[r][c] = "#"
    rest = word[1:]
    return (spell(grid, rest, r + 1, c)
            or spell(grid, rest, r - 1, c)
            or spell(grid, rest, r, c + 1)
            or spell(grid, rest, r, c - 1))

def safe(cols, c):
    row = len(cols)
    for r in range(row):
        if cols[r] == c:
            return False
        if abs(cols[r] - c) == row - r:
            return False
    return True


def place(n, cols):
    if len(cols) == n:
        return 1
    total = 0
    for c in range(n):
        if safe(cols, c):
            cols.append(c)
            total += place(n, cols)
            cols.pop()
    return total
